//	Unseeded: every check here runs against a fresh subject, because
//	          no method here is classified as a write.
//	          A read over an empty subject cannot tell a miss from a bug;
//	          CloserSeed is what closes it.
func AssertCloserContract(t *testing.T, opts ...CloserOption) {
	t.Helper()
	cfg := newCloserConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertCloserContract was given no subject; declare one with " +
			"CloserSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("CloserWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runCloserChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runCloserChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runCloserChecks(
	t *testing.T,
	cfg *closerConfig,
	label string,
	factory func() idempotentclose.Closer,
	wrap func(tb testing.TB, subject idempotentclose.Closer) idempotentclose.Closer,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(closerClose, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onClose {
				cfg.run(t, string(suite.MethodID(closerClose, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		t.Run(closerStats, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onStats {
				cfg.run(t, string(suite.MethodID(closerStats, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap))
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through CloserWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

